toolUseResult.stdout:
// The Agent setup surface. It replaces the dock's body in place rather than
// opening a dialog: setting up an Agent changes nothing about the print, so
// it stays inside the same panel the offer was made in, and every screen can
// be backed out of without leaving anything behind.

import { useEffect, useRef, useState } from 'react';
import { SavedKeyInfo, SetupStatusPayload } from '../bridge/protocol';

// The page and the host ship in the same build, so this list and the host's
// setup_provider_supported() are two views of the same fact. The host still
// validates: an unsupported provider comes back as a visible setup error
// rather than a request that never answers.
interface ProviderOption {
  id: string;
  label: string;
  placeholder: string;
  available: boolean;
}

export const PROVIDERS: ProviderOption[] = [
  { id: 'anthropic', label: 'Anthropic', placeholder: 'sk-ant-…', available: true },
  { id: 'openai', label: 'OpenAI', placeholder: 'sk-…', available: true },
  { id: 'openrouter', label: 'OpenRouter', placeholder: 'sk-or-…', available: true },
  { id: 'other', label: 'Other…', placeholder: '', available: false },
];

// OpenAI stays the tab a new setup opens on; the others are a click away.
export const DEFAULT_PROVIDER = 'openai';

export function providerLabel(id: string | undefined): string {
  return PROVIDERS.find((provider) => provider.id === id)?.label ?? 'your provider';
}

function seconds(elapsedMs: number): string {
  return `${(elapsedMs / 1000).toFixed(1)} s`;
}

export interface SetupChooserProps {
  onUseApiKey: () => void;
  onConnectTool: () => void;
  onDismiss: () => void;
}

export function SetupScreenTitle({ label, onBack }: { label: string; onBack: () => void }) {
  return (
    <div className="setup-card-head">
      <button type="button" className="back" onClick={onBack} aria-label="Back to setup options">
        <span className="chevron" aria-hidden="true" />
      </button>
      <h1>{label}</h1>
    </div>
  );
}

export function SetupChooser({ onUseApiKey, onConnectTool, onDismiss }: SetupChooserProps) {
  const laterTitle = 'This way of connecting an Agent arrives in a later JusPrin release';
  return (
    <div className="pane-state setup" data-testid="setup-chooser">
      <div className="setup-card">
        <div className="setup-card-head">
          <h1>Set up the agent</h1>
          <button className="icon" onClick={onDismiss} aria-label="Close setup">
            <span className="jp-icon jp-icon-close" aria-hidden="true" />
          </button>
        </div>
        <p>
          It reads what you ask for and writes the settings underneath. It needs somewhere to think.
        </p>
        <button className="primary wide" disabled title={laterTitle}>
          Continue with JusPrin
        </button>
        <p className="footnote">Free account · sign in with your browser · nothing to install</p>

        <p className="setup-eyebrow">If you know what these are</p>
        <button className="setup-row" onClick={onUseApiKey} data-testid="setup-row-api-key">
          <span>Use your own API key</span>
          <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
        </button>
        <button className="setup-row" onClick={onConnectTool} data-testid="setup-row-connect-tool">
          <span>Connect an AI tool you already use</span>
          <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
        </button>
      </div>
      <p className="footnote">
        You can change this later. Nothing here is saved in the project.
      </p>
    </div>
  );
}

export interface SetupApiKeyProps {
  setup: SetupStatusPayload;
  // Providers with a stored key, by hint; the key itself never reaches the page.
  savedKeys: SavedKeyInfo[];
  onCheck: (provider: string, apiKey: string) => void;
  onCancel: () => void;
  onRemove: (provider: string) => void;
  onBack: () => void;
}

export function SetupApiKey({ setup, savedKeys, onCheck, onCancel, onRemove, onBack }: SetupApiKeyProps) {
  const [provider, setProvider] = useState(DEFAULT_PROVIDER);
  const [key, setKey] = useState('');
  // Replace opens an empty field beside the saved key, which stays until the
  // new one passes its check.
  const [replacing, setReplacing] = useState(false);
  const [pasteAvailable, setPasteAvailable] = useState(false);
  const input = useRef<HTMLInputElement>(null);

  // Clipboard reads are not granted in every embedded web view; the paste
  // shortcut appears only where it will actually work. Typing and the
  // platform's own paste always do.
  useEffect(() => {
    setPasteAvailable(
      typeof navigator !== 'undefined' && !!navigator.clipboard && typeof navigator.clipboard.readText === 'function',
    );
  }, []);

  const checking = setup.phase === 'checking';
  const option = PROVIDERS.find((candidate) => candidate.id === provider)!;
  const saved = savedKeys.find((candidate) => candidate.provider === provider);

  // A key stored or removed, or another provider chosen, ends a replacement:
  // what the field would have replaced is no longer there.
  useEffect(() => {
    setReplacing(false);
    setKey('');
  }, [provider, saved?.hint]);

  useEffect(() => {
    if (replacing) input.current?.focus();
  }, [replacing]);

  const paste = () => {
    navigator.clipboard
      .readText()
      .then((text) => {
        setKey(text.trim());
        input.current?.focus();
      })
      .catch(() => {
        // Refused at the OS or view level: leave the field alone and let the
        // user paste the way they always could.
        input.current?.focus();
      });
  };

  const submit = () => {
    if (!key.trim() || checking) return;
    onCheck(provider, key.trim());
  };

  const cancelReplace = () => {
    setReplacing(false);
    setKey('');
  };

  // Typing a key: none is saved, or one is being replaced. While a
  // replacement is checked, the saved key is what stays on show.
  const entering = !saved || (replacing && !checking);

  const keyField = entering ? (
    <div className="setup-key">
      <input
        ref={input}
        type="password"
        className="setup-key-input"
        aria-label={`${option.label} API key`}
        placeholder={saved ? 'Paste the new key' : `Paste your ${option.label} key (${option.placeholder})`}
        value={key}
        disabled={checking}
        onChange={(event) => setKey(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter') submit();
          if (event.key === 'Escape' && saved) cancelReplace();
        }}
      />
      {pasteAvailable && (
        <button className="link" onClick={paste} disabled={checking}>
          Paste
        </button>
      )}
    </div>
  ) : (
    <div
      className={saved.rejected && !checking ? 'setup-key setup-key--saved setup-key--rejected' : 'setup-key setup-key--saved'}
      data-testid="setup-key-saved"
    >
      <span className="setup-key-hint" aria-label={`Saved ${option.label} key ${saved.hint}`}>
        {saved.hint}
      </span>
      {!checking && (
        <>
          <button className="link" onClick={() => setReplacing(true)}>
            Replace
          </button>
          <button className="link setup-key-remove" onClick={() => onRemove(provider)}>
            Remove
          </button>
        </>
      )}
    </div>
  );

  return (
    <div className="pane-state setup" data-testid="setup-api-key">
      <div className="setup-card">
        <SetupScreenTitle label="Your own API key" onBack={onBack} />
        <p>Billed by your provider, not JusPrin. Stored on this machine only.</p>

        <div className="setup-tabs" role="tablist" aria-label="Provider">
          {PROVIDERS.map((candidate) => (
            <button
              key={candidate.id}
              role="tab"
              aria-selected={candidate.id === provider}
              className={candidate.id === provider ? 'setup-tab selected' : 'setup-tab'}
              disabled={!candidate.available}
              title={candidate.available ? undefined : `${candidate.label} support arrives in a later JusPrin release`}
              onClick={() => setProvider(candidate.id)}
            >
              {candidate.label}
            </button>
          ))}
        </div>

        {saved && !entering && (
          saved.rejected && !checking ? (
            <span className="setup-key-status setup-key-status--rejected" role="alert" data-testid="setup-key-rejected">
              <span className="jp-icon jp-icon-circle-alert" aria-hidden="true" /> The provider rejected this key
            </span>
          ) : (
            <span className="setup-key-status" data-testid="setup-key-status">
              <span className="jp-icon jp-icon-check" aria-hidden="true" /> Key saved on this computer
            </span>
          )
        )}

        {keyField}

        {saved && !entering && !checking && (
          <p className="setup-key-note">
            {saved.rejected
              ? 'Replace it with a working key, or remove it.'
              : 'JusPrin uses this key for every chat. Replace it to use another one.'}
          </p>
        )}

        {saved && !entering && setup.phase === 'verified' && setup.provider === provider && (
          <div className="setup-actions">
            <SetupResult setup={setup} />
          </div>
        )}

        {saved && !entering && checking ? (
          <div className="setup-actions">
            <span className="setup-result">Checking…</span>
            <button className="link setup-cancel" onClick={onCancel}>
              Cancel
            </button>
          </div>
        ) : (
          entering && (
            <div className="setup-actions">
              <button className="primary" onClick={submit} disabled={checking || key.trim().length === 0}>
                Check key
              </button>
              {checking && (
                <button className="link setup-cancel" onClick={onCancel}>
                  Cancel
                </button>
              )}
              {saved && !checking && (
                <>
                  <button className="link setup-cancel" onClick={cancelReplace}>
                    Cancel
                  </button>
                  <span className="setup-keeps">Keeps {saved.hint}</span>
                </>
              )}
              <SetupResult setup={setup} />
            </div>
          )
        )}

        <p className="footnote">
          Each chat starts on this provider’s recommended model. You can switch the model, or the provider, in any chat.
        </p>
      </div>
    </div>
  );
}

function SetupResult({ setup }: { setup: SetupStatusPayload }) {
  if (setup.phase === 'checking') return <span className="setup-result">Checking…</span>;
  if (setup.phase === 'verified')
    return (
      <span className="setup-result ok" data-testid="setup-verified">
        <span className="jp-icon jp-icon-check" aria-hidden="true" /> replied in {seconds(setup.elapsedMs ?? 0)}
      </span>
    );
  if (setup.phase === 'error')
    return (
      <span className="setup-result error" role="alert" data-testid="setup-error">
        {setup.error?.message ?? 'The key could not be checked.'}
      </span>
    );
  return null;
}

export interface ConnectedBannerProps {
  provider: string;
  warning?: string;
  onDismiss: () => void;
}

// Shown once, immediately after setup succeeds. The durable record of how the
// Agent is connected lives in Preferences; this is only the confirmation that
// the thing the user just did worked.
export function ConnectedBanner({ provider, warning, onDismiss }: ConnectedBannerProps) {
  return (
    <div className={warning ? 'setup-banner warning' : 'setup-banner'} data-testid="setup-connected">
      <span className="setup-banner-text">
        <span className="jp-icon jp-icon-check" aria-hidden="true" />
        <span>Connected · your own {providerLabel(provider)} key{warning ? ` — ${warning}` : ''}</span>
      </span>
      <button className="icon" onClick={onDismiss} aria-label="Dismiss">
        <span className="jp-icon jp-icon-close" aria-hidden="true" />
      </button>
    </div>
  );
}
// A compact, chat-owned account of the setup: what the chat asked for, the
// selected presets, how the agent means to print (its plan's headline), and
// the estimates. Native code supplies the facts; this page presents them.
// Every setting, and what differs from the presets, is on the All settings panel.

import { ReactNode, useState } from 'react';
import { ChangeInfo, SliceEstimateInfo, WorkspaceContext } from '../bridge/protocol';

export interface SetupCardProps {
  context: WorkspaceContext | null;
  working?: boolean;
  historical?: boolean;
  savedAt?: string;
  agentAvailable?: boolean;
  changes?: ChangeInfo[];
  now?: number;
  estimateBefore?: SliceEstimateInfo | null;
  sent?: { at: string; printer: string };
  attention?: Finding[];
  onCompute?: () => void;
  onUndo?: (changeSeq: number) => void;
  onViewSetup?: () => void;
}

export function formatPrintTime(seconds: number): string {
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `~${minutes} min`;
  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
}

export function formatGrams(grams: number): string {
  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
}

export function formatCost(cost: number, currency: string): string {
  if (currency) {
    try {
      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
    } catch {
      // An unknown regional code does not make the native amount disappear.
    }
  }
  return `cost ${cost.toFixed(2)}`;
}

export function formatMoment(value: string | undefined): string {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString(undefined, {
    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
  });
}

export const RECENT_CHANGE_MS = 60000;

export interface EstimateView {
  heading: string;
  metrics: { icon: string; text: string }[];
  cost: string;
  plate: string;
  description: string;
  status: 'current' | 'recomputing' | 'stale' | 'none';
  sliced: boolean;
}

export function estimateView(context: WorkspaceContext): EstimateView {
  const plate = context.plates.find((item) => item.active);
  const view: EstimateView = {
    heading: '', metrics: [], cost: '', plate: plate?.name ?? '', description: '', status: 'none', sliced: !!plate?.sliced,
  };
  if (!plate) return { ...view, description: 'Estimate unavailable' };
  const estimate = plate.estimate;
  const scoped = (text: string) => plate.name ? `${text} · ${plate.name}` : text;
  const metrics: EstimateView['metrics'] = [];
  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0))
    metrics.push({ icon: 'clock', text: formatPrintTime(estimate.printTimeSeconds) });
  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0))
    metrics.push({ icon: 'package', text: formatGrams(estimate.materialGrams) });
  if (plate.estimateStatus === 'recomputing')
    return { ...view, status: 'recomputing', heading: 'Time & material estimates recomputing…',
      description: scoped('Settings confirmed') };
  if (metrics.length === 0)
    return { ...view, description: scoped(plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable') };
  const cost = estimate && estimate.materialCost !== null && estimate.materialCost >= 0.005
    ? formatCost(estimate.materialCost, context.currency) : '';
  if (plate.estimateStatus === 'stale')
    return { ...view, status: 'stale', heading: 'Previous estimates · not current', metrics, cost };
  return { ...view, status: 'current', metrics, cost };
}

export interface Finding { title: string; detail?: string; facts?: string[]; }

export function deterministicAttention(context: WorkspaceContext): Finding[] {
  const review = context.printerReview;
  if (!review) return [];
  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
  const when = formatMoment(review.observed?.observedAt);
  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
    const thing = noun[mismatch.what] ?? 'printer setup';
    if (mismatch.source === 'device') {
      if (!when) return [];
      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
      return [{ title: `Last reported ${thing} differs`,
        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
    }
    return [{ title: `Confirmed ${thing} differs`,
      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
  });
}

export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
  const last = log.at(-1);
  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
  const made = Date.parse(last.createdAt);
  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
  let start = log.length - 1;
  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
  return log.slice(start);
}

export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
  let start = log.length;
  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
  const net = new Map<string, ChangeInfo>();
  for (const change of log.slice(start))
    if (change.kind === 'setting') net.set(change.key || change.label, change);
  return [...net.values()];
}

function estimatePair(estimate: SliceEstimateInfo): string {
  return `${formatPrintTime(estimate.printTimeSeconds)} / ${formatGrams(estimate.materialGrams)}`;
}

function plural(count: number, one: string, many: string): string {
  return `${count} ${count === 1 ? one : many}`;
}

function shortPreset(name: string): string {
  const separator = name.indexOf(' @');
  return separator < 0 ? name : name.slice(0, separator);
}

export function presetsLine(context: WorkspaceContext, title: string): string {
  const process = context.printer.process.trim();
  if (!process) return '';
  const filaments = context.setupIdentity?.filaments ?? [];
  const first = (filaments[0]?.preset || context.printer.filament).trim();
  const filament = first ? `${shortPreset(first)}${filaments.length > 1 ? ` +${filaments.length - 1}` : ''}` : '';
  const parts = title === process ? [filament] : [shortPreset(process), filament];
  return parts.filter(Boolean).join(' · ');
}

// Objects that print with settings of their own. The headline cannot say so,
// and nothing else on the card does.
export function overrideObjectCount(context: WorkspaceContext): number {
  return new Set((context.appliedSetup?.localOverrides ?? [])
    .map((local) => local.object).filter((object): object is number => object !== undefined)).size;
}

export interface SetupPresentationOptions {
  historical?: boolean;
  working?: boolean;
  agentAvailable?: boolean;
  changes?: ChangeInfo[];
  now?: number;
  sent?: { at: string; printer: string };
  savedAt?: string;
}

// What the card and the setup page both say about themselves: their label,
// their one state, their title. Conversation status outranks live activity: a
// saved card is never working, whatever the active chat happens to be doing.
export function setupPresentation(context: WorkspaceContext, options: SetupPresentationOptions = {}) {
  const historical = !!options.historical;
  const working = !!options.working && !historical;
  const estimate = estimateView(context);
  const intent = context.setupIntent.trim();
  const title = intent || context.printer.process.trim();
  // Nothing vouches for this setup but the preset the person picked: no agent
  // is configured, or the host read no settings to compare with it.
  const noAgent = !historical && options.agentAvailable === false;
  if (noAgent || (!historical && !context.appliedSetup && !intent))
    return { label: 'Preset fallback', state: noAgent ? 'No agent' : null as ReactNode, title: context.printer.process.trim(),
      estimate, justChanged: [], edited: [], editedByYou: false, outOfDate: false, live: true, fallback: true, noAgent };
  const justChanged = historical ? [] : recentAgentChange(options.changes, options.now ?? Date.now());
  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(options.changes);
  // "Edited by you" needs a setup the agent had a hand in; without one a
  // hand edit is simply how the project was made.
  const agentManaged = !!intent || (options.changes ?? []).some((change) => change.actor === 'agent');
  const editedByYou = edited.length > 0 && agentManaged;
  // Out of date stands the card down: it drops the accent, as a saved card
  // does, because it no longer vouches for the numbers under it.
  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
  const saved = formatMoment(options.savedAt);
  const label = options.sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
  const state: ReactNode = historical
    ? options.sent ? 'Sliced & sent' : estimate.status === 'stale' ? 'Out of date'
      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
    : working ? 'Agent working' : justChanged.length > 0 ? 'Updated'
    : estimate.status === 'recomputing' ? 'Confirmed' : editedByYou ? 'Edited by you'
    : outOfDate ? 'Out of date' : estimate.status === 'none' && !estimate.sliced ? 'Not sliced' : 'Current';
  return { label, state, title, estimate, justChanged, edited, editedByYou, outOfDate, live: !historical && !outOfDate,
    fallback: false, noAgent: false };
}

function Metrics({ estimate }: { estimate: EstimateView }) {
  return <div className="current-setup-metrics">
    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
    {estimate.plate && <span className="current-setup-metric">
      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
  </div>;
}

function Attention({ findings }: { findings: Finding[] }) {
  const [open, setOpen] = useState(false);
  if (findings.length === 0) return null;
  const first = findings[0];
  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings')
    : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
  return <>
    <div className="current-setup-attention">
      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
      {first.detail && <p className="current-setup-line">{first.detail}</p>}
      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
        Review {subject}</button>}
      {open && <ul className="current-setup-findings">{findings.map((finding, index) => <li key={index}>
        {findings.length > 1 && <strong>{finding.title}</strong>}
        {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
      </li>)}</ul>}
    </div>
    <hr className="current-setup-divider" />
  </>;
}

