101	export function SetupApiKey({ setup, savedKeys, onCheck, onCancel, onRemove, onBack }: SetupApiKeyProps) {
102	  const [provider, setProvider] = useState(DEFAULT_PROVIDER);
103	  const [key, setKey] = useState('');
104	  // Replace opens an empty field beside the saved key, which stays until the
105	  // new one passes its check.
106	  const [replacing, setReplacing] = useState(false);
107	  const [pasteAvailable, setPasteAvailable] = useState(false);
108	  const input = useRef<HTMLInputElement>(null);
109	
110	  // Clipboard reads are not granted in every embedded web view; the paste
111	  // shortcut appears only where it will actually work. Typing and the
112	  // platform's own paste always do.
113	  useEffect(() => {
114	    setPasteAvailable(
115	      typeof navigator !== 'undefined' && !!navigator.clipboard && typeof navigator.clipboard.readText === 'function',
116	    );
117	  }, []);
118	
119	  const checking = setup.phase === 'checking';
120	  const option = PROVIDERS.find((candidate) => candidate.id === provider)!;
121	  const saved = savedKeys.find((candidate) => candidate.provider === provider);
122	
123	  // A key stored or removed, or another provider chosen, ends a replacement:
124	  // what the field would have replaced is no longer there.
125	  useEffect(() => {
126	    setReplacing(false);
127	    setKey('');
128	  }, [provider, saved?.hint]);
129	
130	  useEffect(() => {
131	    if (replacing) input.current?.focus();
132	  }, [replacing]);
133	
134	  const paste = () => {
135	    navigator.clipboard
136	      .readText()
137	      .then((text) => {
138	        setKey(text.trim());
139	        input.current?.focus();
140	      })
141	      .catch(() => {
142	        // Refused at the OS or view level: leave the field alone and let the
143	        // user paste the way they always could.
144	        input.current?.focus();
145	      });
146	  };
147	
148	  const submit = () => {
149	    if (!key.trim() || checking) return;
150	    onCheck(provider, key.trim());
151	  };
152	
153	  const cancelReplace = () => {
154	    setReplacing(false);
155	    setKey('');
156	  };
157	
158	  // Typing a key: none is saved, or one is being replaced. While a
159	  // replacement is checked, the saved key is what stays on show.
160	  const entering = !saved || (replacing && !checking);
