179	        <button className="link" onClick={paste} disabled={checking}>
180	          Paste
181	        </button>
182	      )}
183	    </div>
184	  ) : (
185	    <div
186	      className={saved.rejected && !checking ? 'setup-key setup-key--saved setup-key--rejected' : 'setup-key setup-key--saved'}
187	      data-testid="setup-key-saved"
