189	      <span className="setup-key-hint" aria-label={`Saved ${option.label} key ${saved.hint}`}>
190	        {saved.hint}
191	      </span>
192	      {!checking && (
193	        <>
194	          <button className="link" onClick={() => setReplacing(true)}>
195	            Replace
196	          </button>
