426	export function deterministicAttention(context: WorkspaceContext): Finding[] {
427	  const review = context.printerReview;
428	  if (!review) return [];
429	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
430	  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
431	  const when = formatMoment(review.observed?.observedAt);
432	  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
433	    const thing = noun[mismatch.what] ?? 'printer setup';
434	    if (mismatch.source === 'device') {
435	      if (!when) return [];
436	      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
437	      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
438	      return [{ title: `Last reported ${thing} differs`,
439	        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
440	    }
441	    return [{ title: `Confirmed ${thing} differs`,
442	      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
443	      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
444	  });
445	}
446	
447	export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
448	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
449	  const last = log.at(-1);
450	  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
451	  const made = Date.parse(last.createdAt);
452	  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
453	  let start = log.length - 1;
454	  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
455	    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
456	  return log.slice(start);
457	}
458	
459	export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
460	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
461	  let start = log.length;
462	  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
463	  const net = new Map<string, ChangeInfo>();
464	  for (const change of log.slice(start))
465	    if (change.kind === 'setting') net.set(change.key || change.label, change);
466	  return [...net.values()];
467	}
468	
469	function estimatePair(estimate: SliceEstimateInfo): string {
470	  return `${formatPrintTime(estimate.printTimeSeconds)} / ${formatGrams(estimate.materialGrams)}`;
471	}
472	
473	function plural(count: number, one: string, many: string): string {
474	  return `${count} ${count === 1 ? one : many}`;
475	}
476	
477	function shortPreset(name: string): string {
478	  const separator = name.indexOf(' @');
479	  return separator < 0 ? name : name.slice(0, separator);
480	}
481	
482	export function presetsLine(context: WorkspaceContext, title: string): string {
483	  const process = context.printer.process.trim();
484	  if (!process) return '';
485	  const filaments = context.setupIdentity?.filaments ?? [];
486	  const first = (filaments[0]?.preset || context.printer.filament).trim();
487	  const filament = first ? `${shortPreset(first)}${filaments.length > 1 ? ` +${filaments.length - 1}` : ''}` : '';
488	  const parts = title === process ? [filament] : [shortPreset(process), filament];
489	  return parts.filter(Boolean).join(' · ');
490	}
491	
492	// Objects that print with settings of their own. The headline cannot say so,
493	// and nothing else on the card does.
494	export function overrideObjectCount(context: WorkspaceContext): number {
495	  return new Set((context.appliedSetup?.localOverrides ?? [])
496	    .map((local) => local.object).filter((object): object is number => object !== undefined)).size;
497	}
498	
499	export interface SetupPresentationOptions {
500	  historical?: boolean;
501	  working?: boolean;
502	  agentAvailable?: boolean;
503	  changes?: ChangeInfo[];
504	  now?: number;
505	  sent?: { at: string; printer: string };
506	  savedAt?: string;
507	}
508	
509	// What the card and the setup page both say about themselves: their label,
510	// their one state, their title. Conversation status outranks live activity: a
511	// saved card is never working, whatever the active chat happens to be doing.
512	export function setupPresentation(context: WorkspaceContext, options: SetupPresentationOptions = {}) {
513	  const historical = !!options.historical;
514	  const working = !!options.working && !historical;
515	  const estimate = estimateView(context);
516	  const intent = context.setupIntent.trim();
517	  const title = intent || context.printer.process.trim();
518	  // Nothing vouches for this setup but the preset the person picked: no agent
519	  // is configured, or the host read no settings to compare with it.
520	  const noAgent = !historical && options.agentAvailable === false;
521	  if (noAgent || (!historical && !context.appliedSetup && !intent))
522	    return { label: 'Preset fallback', state: noAgent ? 'No agent' : null as ReactNode, title: context.printer.process.trim(),
523	      estimate, justChanged: [], edited: [], editedByYou: false, outOfDate: false, live: true, fallback: true, noAgent };
524	  const justChanged = historical ? [] : recentAgentChange(options.changes, options.now ?? Date.now());
525	  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(options.changes);
526	  // "Edited by you" needs a setup the agent had a hand in; without one a
527	  // hand edit is simply how the project was made.
528	  const agentManaged = !!intent || (options.changes ?? []).some((change) => change.actor === 'agent');
529	  const editedByYou = edited.length > 0 && agentManaged;
530	  // Out of date stands the card down: it drops the accent, as a saved card
531	  // does, because it no longer vouches for the numbers under it.
532	  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
533	  const saved = formatMoment(options.savedAt);
534	  const label = options.sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
535	  const state: ReactNode = historical
536	    ? options.sent ? 'Sliced & sent' : estimate.status === 'stale' ? 'Out of date'
537	      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
538	    : working ? 'Agent working' : justChanged.length > 0 ? 'Updated'
539	    : estimate.status === 'recomputing' ? 'Confirmed' : editedByYou ? 'Edited by you'
540	    : outOfDate ? 'Out of date' : estimate.status === 'none' && !estimate.sliced ? 'Not sliced' : 'Current';
541	  return { label, state, title, estimate, justChanged, edited, editedByYou, outOfDate, live: !historical && !outOfDate,
542	    fallback: false, noAgent: false };
543	}
544	
545	function Metrics({ estimate }: { estimate: EstimateView }) {
546	  return <div className="current-setup-metrics">
547	    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
548	      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
549	    {estimate.plate && <span className="current-setup-metric">
550	      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
551	    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
552	  </div>;
553	}
554	
555	function Attention({ findings }: { findings: Finding[] }) {
556	  const [open, setOpen] = useState(false);
557	  if (findings.length === 0) return null;
558	  const first = findings[0];
559	  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
560	  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings')
561	    : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
562	  return <>
563	    <div className="current-setup-attention">
564	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
565	      {first.detail && <p className="current-setup-line">{first.detail}</p>}
566	      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
567	        Review {subject}</button>}
568	      {open && <ul className="current-setup-findings">{findings.map((finding, index) => <li key={index}>
569	        {findings.length > 1 && <strong>{finding.title}</strong>}
570	        {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
571	      </li>)}</ul>}
572	    </div>
573	    <hr className="current-setup-divider" />
574	  </>;
575	}
576	
577	export function SetupCard({ context, working: busy = false, historical = false, savedAt, agentAvailable = true,
578	  changes, now = Date.now(), estimateBefore, sent, attention = [], onCompute, onUndo, onViewSetup }: SetupCardProps) {
579	  if (!context) return null;
580	  // A saved card is never working, whatever the active chat happens to be
581	  // doing.
582	  const working = busy && !historical;
583	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
584	  const presentation = setupPresentation(context, { historical, working, agentAvailable, changes, now, sent, savedAt });
585	
586	  if (presentation.fallback) {
587	    const { estimate, title } = presentation;
588	    return <section className="current-setup current-setup--live" data-testid="current-setup" aria-label={ariaLabel}>
589	      <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
590	        {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
591	      {title && <h2 className="current-setup-title" title={title}>{title}</h2>}
592	      {presentation.noAgent ? <p className="current-setup-line">No agent configured · using the selected preset.</p>
593	        : estimate.metrics.length > 0 ? <Metrics estimate={estimate} />
594	        : <p className="current-setup-line">{estimate.description}</p>}
595	    </section>;
596	  }
597	
598	  const { estimate, justChanged, edited, editedByYou, outOfDate } = presentation;
599	  // The plan's headline in every state the card has: the state label and the
600	  // notices say how far the card can be trusted. With no plan pinned there is
601	  // no line at all.
602	  const headline = context.planHeadline.trim();
603	  const objects = overrideObjectCount(context);
604	  const presets = presetsLine(context, presentation.title);
605	
606	  const withheld = editedByYou && estimate.status === 'stale';
607	  const heading = withheld ? '' : estimate.heading ? estimate.heading : estimate.metrics.length === 0 ? ''
608	    : sent ? 'Saved pre-slice estimates' : working ? 'Last confirmed estimates' : '';
609	  const description = withheld ? (estimate.plate ? `Estimate unavailable for these edits · ${estimate.plate}`
610	    : 'Estimate unavailable for these edits') : estimate.description;
611	  const canCompute = !historical && !working && !!onCompute && estimate.status === 'none';
612	  // What the card adds for the minute a change is new. The settings the
613	  // agent changed are not listed: the thread's change rows under its turn
614	  // name them, and the setup page lists every difference. A project step is
615	  // named here, and it is the one thing Orca can undo: its undo takes the top
616	  // of its own stack, and a preset edit is not on it.
617	  const last = justChanged.at(-1);
618	  const step = !working && last?.kind === 'step' ? last : undefined;
619	  const undoable = !!onUndo && !!step && context.history.canUndo;
620	  const plate = context.plates.find((item) => item.active);
621	  const after = plate?.estimate;
622	  const estimateDelta = justChanged.length > 0 && estimateBefore && after && estimate.status === 'current' &&
623	    (estimateBefore.printTimeSeconds !== after.printTimeSeconds || estimateBefore.materialGrams !== after.materialGrams)
624	    ? `Estimate: ${estimatePair(estimateBefore)} → ${estimatePair(after)}` : '';
625	  const named = edited.slice(0, 2).map((change) => `${change.label} ${change.to || 'none'}`);
626	  const editedText = edited.length > 2 ? `${named.join(', ')} and ${plural(edited.length - 2, 'more setting', 'more settings')}`
627	    : named.join(' and ');
628	  const findings = [...deterministicAttention(context), ...attention];
629	
630	  return <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}
631	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
632	    <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
633	      {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
634	    {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
635	    {presets && <p className="current-setup-line current-setup-line--single" title={presets}>{presets}</p>}
636	    {headline && <p className="current-setup-strategy">{headline}</p>}
637	    {objects > 0 && <p className="current-setup-note">
638	      {plural(objects, 'object with overrides', 'objects with overrides')}</p>}
639	    {heading && <p className="current-setup-heading">{heading}</p>}
640	    {!withheld && estimate.metrics.length > 0 && <Metrics estimate={estimate} />}
641	    {description && <p className="current-setup-line">{description}</p>}
642	    {sent && estimate.metrics.length > 0 && <p className="current-setup-line">Actual time &amp; material unavailable.</p>}
643	    {canCompute && <button type="button" className="current-setup-link" onClick={onCompute}>Compute estimates</button>}
644	    <hr className="current-setup-divider" />
645	    {working && <><p className="current-setup-line">Agent is applying and evaluating changes…<br />
646	      Shown settings remain the last confirmed setup.</p><hr className="current-setup-divider" /></>}
647	    {!working && (step || estimateDelta) && <>
648	      {step && <p className="current-setup-line">{step.label || 'Object settings changed'}</p>}
649	      {estimateDelta && <p className="current-setup-line">{estimateDelta}</p>}
650	      {undoable && <button type="button" className="current-setup-link" onClick={() => onUndo!(step!.seq)}>Undo</button>}
651	      <hr className="current-setup-divider" />
652	    </>}
653	    {outOfDate && <><div className="current-setup-attention">
654	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
655	        {historical ? 'These estimates were already out of date when saved.' : 'Estimates no longer match the current project.'}</p>
656	      {plate?.invalidatedBy && <p className="current-setup-line">{plate.invalidatedBy}</p>}
657	      {!historical && onCompute && <button type="button" className="current-setup-link" onClick={onCompute}>
658	        Refresh setup &amp; recompute</button>}
659	    </div><hr className="current-setup-divider" /></>}
660	    {editedByYou && <><p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
661	      <span>You set {editedText} outside the agent. Your current settings are preserved.</span></p>
662	      <hr className="current-setup-divider" /></>}
663	    <Attention findings={findings} />
664	    <button type="button" className="current-setup-link" onClick={onViewSetup}>All settings</button>
665	    {historical && <><hr className="current-setup-divider" />
666	      {sent && <p className="current-setup-sent">{[formatMoment(sent.at), sent.printer && `sent to ${sent.printer}`]
667	        .filter(Boolean).join(' · ')}</p>}
668	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
669	        <span>{sent ? 'Saved snapshot.' : 'Saved with this chat.'} The canvas shows your current project.</span></p>
670	    </>}
671	  </section>;
672	}
673

