/* Expanded button from the token file: 12x8 padding, standard radius, Body. */
button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font: var(--font-body);
  padding: var(--button-secondary-padding);
  border-radius: var(--radius-small);
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
}

button:hover:enabled {
  border-color: var(--border-subtle);
}

button:disabled {
  color: var(--text-secondary);
  cursor: default;
}

/* The design system's Button/Primary: the primary recipe's padding, Body
   Small Bold and the branded medium radius, 34 high with no border. */
button.primary {
  padding: var(--button-primary-padding);
  border: 0;
  border-radius: var(--radius-medium);
  background: var(--action-primary);
  color: var(--action-primary-text);
  font: var(--font-body-small-bold);
}

button.primary:hover:enabled {
  background: var(--action-primary-hover);
  border-color: transparent;
}

button.primary:active:enabled {
  background: var(--action-primary-pressed);
  border-color: transparent;
}

button.primary:disabled {
  background: var(--action-primary);
  color: var(--action-primary-text);
  opacity: 0.4;
}

button.icon {
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: var(--radius-small);
  color: var(--text-secondary);
}

button.icon:hover:enabled {
  background: var(--surface-subtle);
  border-color: transparent;
}

button.back {
  width: 12px;
  height: 12px;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: var(--text-primary);
}

button.back:hover:enabled,
button.back:active:enabled {
  background: transparent;
  border: none;
}

/* Icons are SVGs from resources/jusprin/ui/icons drawn as masks so they take
   the button's current color in both appearances. */
button.back .chevron {
  display: block;
  width: 12px;
  height: 12px;
  background: currentColor;
  -webkit-mask: url('@resources/jusprin/ui/icons/chevron-left.svg') center / 12px 12px no-repeat;
  mask: url('@resources/jusprin/ui/icons/chevron-left.svg') center / 12px 12px no-repeat;
}

/* The design system's Button/Link: text only, Label Bold, action/primary.
   The setup card, the project-updates strip, the printer panel's and the
   setup page's headers all use it. */
button.link,
.current-setup-link,
.project-updates-link,
.panel-link-button {
  height: var(--button-link-height);
  padding: var(--button-link-padding);
  border: 0;
  border-radius: var(--radius-small);
  background: none;
  font: var(--font-label-bold);
  color: var(--action-primary);
  cursor: pointer;
}

button.link:hover:enabled,
.current-setup-link:hover:enabled,
.project-updates-link:hover:enabled,
.panel-link-button:hover:enabled {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

button.link:active:enabled,
.current-setup-link:active:enabled,
.project-updates-link:active:enabled,
.panel-link-button:active:enabled {
  color: var(--action-primary-pressed);
}

button.link:disabled,
.current-setup-link:disabled,
.project-updates-link:disabled,
.panel-link-button:disabled {
  color: var(--action-disabled-text);
}

