  margin: 0;
}

.setup-card p {
  margin: 0;
  font: var(--font-body-small);
  color: var(--text-secondary);
}

button.primary.wide {
  width: 100%;
}

button.wide {
  width: 100%;
}

.setup-eyebrow {
  margin: 8px 0 0;
  font: var(--font-metadata);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
