// node capture.mjs <page.html> <outDir>
import { spawn } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const [, , page, outDir] = process.argv;
mkdirSync(outDir, { recursive: true });
const port = 9444;
const edge = spawn('C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', [
  '--headless=new', `--remote-debugging-port=${port}`, '--user-data-dir=C:/b/aps/edge', '--hide-scrollbars',
  '--force-device-scale-factor=2', '--window-size=1000,1000', 'about:blank',
], { stdio: 'ignore' });

let targets;
for (let i = 0; i < 50; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if (targets.some((t) => t.type === 'page')) break; } catch {}
  await new Promise((r) => setTimeout(r, 200));
}
const socket = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((r) => socket.addEventListener('open', r));
let next = 0;
const call = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++next;
  const on = (event) => {
    const m = JSON.parse(event.data);
    if (m.id !== id) return;
    socket.removeEventListener('message', on);
    m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result);
  };
  socket.addEventListener('message', on);
  socket.send(JSON.stringify({ id, method, params }));
});
await call('Page.enable');

const cases = [
  ['setup-chooser', '01-chooser'],
  ['api-key-none', '02-api-key-1-no-key'],
  ['api-key-entering', '03-api-key-2-entering'],
  ['api-key-checking', '04-api-key-3-checking'],
  ['api-key-could-not-check', '05-api-key-4-could-not-check'],
  ['api-key-saved', '06-api-key-5-saved'],
  ['api-key-replacing', '07-api-key-6-replacing'],
  ['api-key-rejected', '08-api-key-7-rejected'],
  ['api-key-session-only', '09-api-key-8-working-until-restart'],
  ['setup-tools', '10-connect-ai-tool'],
  ['setup-connected', '11-connected-banner'],
  ['setup-connected-not-stored', '12-connected-banner-key-not-stored'],
];
for (const mode of ['light', 'dark']) {
  for (const [id, name] of cases) {
    const url = `${pathToFileURL(page).href}?show=${id}&mode=${mode}&dock=429&height=746`;
    const loaded = new Promise((r) => { const on = (e) => { if (JSON.parse(e.data).method === 'Page.loadEventFired') { socket.removeEventListener('message', on); r(); } }; socket.addEventListener('message', on); });
    await call('Page.navigate', { url });
    await loaded;
    await new Promise((r) => setTimeout(r, 300));
    const { result } = await call('Runtime.evaluate', { returnByValue: true, expression:
      `(() => { const f = [...document.querySelectorAll('figure')].find((x) => !x.hidden); const r = f.querySelector('.stage').getBoundingClientRect(); return { x: r.x, y: r.y + scrollY, width: r.width, height: r.height }; })()` });
    const shot = await call('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true, clip: { ...result.value, scale: 1 } });
    writeFileSync(`${outDir}/${name}-${mode}.png`, Buffer.from(shot.data, 'base64'));
    console.log('wrote', `${name}-${mode}.png`);
  }
}
socket.close();
edge.kill();
process.exit(0);

